import{_ as e,o as l,c as r,a2 as t}from"./chunks/framework.z3u3TMv0.js";const h=JSON.parse('{"title":"安装 llama.cpp","description":"使用 llama.cpp / llama-server 加载 GGUF，为 MiniTavern 提供 OpenAI 兼容接口。","frontmatter":{"title":"安装 llama.cpp","description":"使用 llama.cpp / llama-server 加载 GGUF，为 MiniTavern 提供 OpenAI 兼容接口。","head":[["meta",{"property":"og:title","content":"安装 llama.cpp · MiniTavern Docs"}],["meta",{"property":"og:description","content":"使用 llama.cpp / llama-server 加载 GGUF，为 MiniTavern 提供 OpenAI 兼容接口。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/llamacpp/install"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/llamacpp/install"}]]},"headers":[],"relativePath":"llamacpp/install.md","filePath":"llamacpp/install.md","lastUpdated":1786329914000}'),i={name:"llamacpp/install.md"};function n(o,a,p,s,c,m){return l(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="安装与上手-llama-cpp" tabindex="-1">安装与上手（llama.cpp） <a class="header-anchor" href="#安装与上手-llama-cpp" aria-label="Permalink to &quot;安装与上手（llama.cpp）&quot;">​</a></h1><p><a href="https://github.com/ggerganov/llama.cpp" target="_blank" rel="noreferrer">llama.cpp</a> 提供高性能 GGUF 推理；其中的 <strong><code>llama-server</code></strong>（或发行版中的 server 二进制）可暴露 HTTP API，供 MiniTavern 使用。</p><p>适合：已经会下 GGUF、希望依赖少、参数可控的用户。新手若只想点选下载，可先看 <a href="/ultra_guides/lmstudio/install">LM Studio</a> 或 <a href="/ultra_guides/ollama/install">Ollama</a>。</p><h2 id="获取" tabindex="-1">获取 <a class="header-anchor" href="#获取" aria-label="Permalink to &quot;获取&quot;">​</a></h2><ol><li>从官方仓库 Releases 下载预编译包，或按文档自行编译（CUDA / Metal / Vulkan）。</li><li>确认包内有 <strong>server</strong> 相关可执行文件（名称可能为 <code>llama-server</code>、<code>server</code> 等，以你下载的版本为准）。</li><li>准备 GGUF 模型，见 <a href="/ultra_guides/local/models">推荐模型</a>。</li></ol><h2 id="快速验证" tabindex="-1">快速验证 <a class="header-anchor" href="#快速验证" aria-label="Permalink to &quot;快速验证&quot;">​</a></h2><p>在模型能本机推理后，再开启 HTTP 服务（见下一页）。先保证命令行加载模型无报错。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p><a href="./server">开启 server</a> → <a href="/ultra_guides/connect-app/minitavern">在 MiniTavern 中配置</a></p>',9)])])}const u=e(i,[["render",n]]);export{h as __pageData,u as default};
